css:
:root {
  --bg-primary: #0b0e1a;
  --bg-secondary: #111527;
  --bg-tertiary: #181d35;
  --bg-card: #141829;
  --bg-hover: #1e2340;
  --bg-active: #252b4a;
  --bg-input: #0f1322;
  --bg-overlay: rgba(8, 10, 22, 0.85);
  --text-primary: #c8cde0;
  --text-secondary: #8a90a8;
  --text-muted: #555b75;
  --text-link: #6a8adf;
  --text-heading: #dce0f0;
  --accent-primary: #4a6abf;
  --accent-secondary: #3b5498;
  --accent-hover: #5878d0;
  --accent-border: #2a3565;
  --accent-glow: rgba(74, 106, 191, 0.15);
}

body {
  background: var(--bg-primary);
  color: var(--text-primary);
}

.cs-card {
  background: var(--bg-card);
  border: 1px solid var(--accent-border);
}

a {
  color: var(--text-link);
}
